export type AspectRatio = '1:1' | '2:3' | '3:4' | '9:16' | '16:9';

export type EngineProvider = 'gemini-imagen' | 'flux-free' | 'pixai';

export interface ModelOption {
  id: string;
  name: string;
  series: string;
  badge: string;
  description: string;
  samplePrompt: string;
  provider: EngineProvider;
}

export type GenerationStatus = 'idle' | 'submitting' | 'queued' | 'denoising' | 'decoding' | 'completed' | 'error';

export interface ArtAsset {
  id: string;
  prompt: string;
  negativePrompt: string;
  modelId: string;
  modelName: string;
  aspectRatio: AspectRatio;
  imageUrl: string;
  createdAt: string;
  seed: number;
  isLiveApi: boolean;
  provider: EngineProvider;
  character?: string;
}

export interface PresetItem {
  id: string;
  title: string;
  character: string;
  tagline: string;
  prompt: string;
  negativePrompt: string;
  ratio: AspectRatio;
  modelId: string;
  accent: string;
  previewUrl: string;
}

export type AppNavigationMode = 'visual-studio' | 'novel-codex' | 'narrative-outliner';

export type CodexCategory = 'character' | 'faction' | 'technology' | 'location';

export interface CodexEntity {
  id: string;
  category: CodexCategory;
  name: string;
  role: string;
  tagline: string;
  age?: string;
  height?: string;
  visualTags: string;
  psychology: string;
  backstory: string;
  accent: string;
  imageUrl?: string;
  promptPresetId?: string;
}

export interface OutlinerNode {
  id: string;
  actTitle: string;
  chapterNumber: number;
  title: string;
  oneLineSummary: string;
  beats: string[];
  keyCharacters: string[];
  location: string;
  isFolded: boolean;
  status: 'canon' | 'draft';
}

export interface OutlinerPathway {
  id: string;
  parentNodeId: string;
  title: string;
  trajectory: string;
  consequences: string;
  beats: string[];
  conflictType: 'kinetic' | 'cyber' | 'psychological' | 'infiltrative';
  isSelected: boolean;
}

