1	:root {
2	  --bg-core: #07090e;
3	  --bg-surface: #0e121a;
4	  --bg-panel: rgba(18, 23, 34, 0.75);
5	  --bg-card: rgba(24, 30, 46, 0.6);
6	  --bg-input: #121622;
7	  --bg-hover: rgba(255, 255, 255, 0.04);
8	  --bg-active: rgba(0, 240, 255, 0.08);
9	
10	  --border-subtle: rgba(255, 255, 255, 0.07);
11	  --border-glow: rgba(0, 240, 255, 0.3);
12	  --border-focus: #00f0ff;
13	  --border-rose: rgba(255, 42, 133, 0.4);
14	
15	  --text-main: #f1f5f9;
16	  --text-muted: #94a3b8;
17	  --text-dim: #64748b;
18	  --text-cyan: #00f0ff;
19	  --text-rose: #ff2a85;
20	
21	  --accent-cyan: #00f0ff;
22	  --accent-cyan-rgb: 0, 240, 255;
23	  --accent-rose: #ff2a85;
24	  --accent-purple: #a855f7;
25	  --accent-amber: #f59e0b;
26	
27	  --glow-cyan: 0 0 24px rgba(0, 240, 255, 0.25);
28	  --glow-rose: 0 0 24px rgba(255, 42, 133, 0.25);
29	  --radius-sm: 8px;
30	  --radius-md: 12px;
31	  --radius-lg: 18px;
32	  --radius-xl: 24px;
33	
34	  --font-heading: 'Outfit', sans-serif;
35	  --font-body: 'Inter', -apple-system, sans-serif;
36	  --font-mono: 'JetBrains Mono', monospace;
37	
38	  --shadow-panel: 0 20px 40px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.05);
39	}
40	
41	* {
42	  box-sizing: border-box;
43	  margin: 0;
44	  padding: 0;
45	}
46	
47	body {
48	  background-color: var(--bg-core);
49	  color: var(--text-main);
50	  font-family: var(--font-body);
51	  min-height: 100vh;
52	  overflow-x: hidden;
53	  background-image: 
54	    radial-gradient(circle at 15% 15%, rgba(0, 240, 255, 0.04) 0%, transparent 40%),
55	    radial-gradient(circle at 85% 85%, rgba(255, 42, 133, 0.04) 0%, transparent 40%),
56	    linear-gradient(180deg, #07090e 0%, #0a0d14 100%);
57	  background-attachment: fixed;
58	  -webkit-font-smoothing: antialiased;
59	}
60	
61	/* Custom Scrollbar */
62	::-webkit-scrollbar {
63	  width: 6px;
64	  height: 6px;
65	}
66	::-webkit-scrollbar-track {
67	  background: var(--bg-core);
68	}
69	::-webkit-scrollbar-thumb {
70	  background: rgba(255, 255, 255, 0.15);
71	  border-radius: 999px;
72	}
73	::-webkit-scrollbar-thumb:hover {
74	  background: var(--accent-cyan);
75	}
76	
77	/* App Container */
78	.app-container {
79	  display: flex;
80	  flex-direction: column;
81	  min-height: 100vh;
82	}
83	
84	/* Header */
85	.app-header {
86	  height: 72px;
87	  min-height: 72px;
88	  display: flex;
89	  align-items: center;
90	  justify-content: space-between;
91	  padding: 0 28px;
92	  background: rgba(14, 18, 26, 0.85);
93	  backdrop-filter: blur(20px);
94	  border-bottom: 1px solid var(--border-subtle);
95	  position: sticky;
96	  top: 0;
97	  z-index: 50;
98	}
99	
100	.brand-wrapper {
101	  display: flex;
102	  align-items: center;
103	  gap: 14px;
104	}
105	
106	.brand-icon {
107	  width: 40px;
108	  height: 40px;
109	  border-radius: var(--radius-md);
110	  background: linear-gradient(135deg, rgba(0, 240, 255, 0.2), rgba(255, 42, 133, 0.2));
111	  border: 1px solid rgba(0, 240, 255, 0.4);
112	  display: flex;
113	  align-items: center;
114	  justify-content: center;
115	  color: var(--accent-cyan);
116	  box-shadow: var(--glow-cyan);
117	}
118	
119	.brand-title {
120	  font-family: var(--font-heading);
121	  font-size: 1.25rem;
122	  font-weight: 800;
123	  letter-spacing: -0.02em;
124	  background: linear-gradient(90deg, #ffffff, #94a3b8);
125	  -webkit-background-clip: text;
126	  -webkit-text-fill-color: transparent;
127	  display: flex;
128	  align-items: center;
129	  gap: 8px;
130	}
131	
132	.brand-badge {
133	  font-size: 0.65rem;
134	  font-weight: 700;
135	  letter-spacing: 0.08em;
136	  text-transform: uppercase;
137	  padding: 2px 8px;
138	  border-radius: 999px;
139	  background: rgba(0, 240, 255, 0.12);
140	  color: var(--accent-cyan);
141	  border: 1px solid rgba(0, 240, 255, 0.3);
142	}
143	
144	.header-actions {
145	  display: flex;
146	  align-items: center;
147	  gap: 12px;
148	}
149	
150	.mode-indicator {
151	  display: flex;
152	  align-items: center;
153	  gap: 8px;
154	  padding: 6px 14px;
155	  border-radius: 999px;
156	  background: rgba(255, 255, 255, 0.04);
157	  border: 1px solid var(--border-subtle);
158	  font-size: 0.8rem;
159	  font-weight: 600;
160	}
161	
162	.mode-dot {
163	  width: 8px;
164	  height: 8px;
165	  border-radius: 50%;
166	  background: #10b981;
167	  box-shadow: 0 0 8px #10b981;
168	}
169	
170	.mode-dot.preview {
171	  background: var(--accent-amber);
172	  box-shadow: 0 0 8px var(--accent-amber);
173	}
174	
175	.btn-ghost {
176	  min-height: 44px;
177	  padding: 0 16px;
178	  border-radius: var(--radius-md);
179	  background: transparent;
180	  border: 1px solid var(--border-subtle);
181	  color: var(--text-main);
182	  font-family: var(--font-body);
183	  font-size: 0.85rem;
184	  font-weight: 600;
185	  display: flex;
186	  align-items: center;
187	  gap: 8px;
188	  cursor: pointer;
189	  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
190	}
191	
192	.btn-ghost:hover {
193	  background: rgba(255, 255, 255, 0.06);
194	  border-color: rgba(255, 255, 255, 0.2);
195	  transform: translateY(-1px);
196	}
197	
198	/* Studio Layout */
199	.studio-layout {
200	  display: grid;
201	  grid-template-columns: 460px 1fr;
202	  flex: 1;
203	  gap: 24px;
204	  padding: 24px 28px;
205	  max-width: 1720px;
206	  margin: 0 auto;
207	  width: 100%;
208	}
209	
210	@media (max-width: 1100px) {
211	  .studio-layout {
212	    grid-template-columns: 1fr;
213	  }
214	}
215	
216	/* Glass Panels */
217	.glass-panel {
218	  background: var(--bg-panel);
219	  backdrop-filter: blur(24px);
220	  border: 1px solid var(--border-subtle);
221	  border-radius: var(--radius-xl);
222	  box-shadow: var(--shadow-panel);
223	  display: flex;
224	  flex-direction: column;
225	  overflow: hidden;
226	}
227	
228	/* Left Panel - Control Deck */
229	.control-deck {
230	  padding: 24px;
231	  gap: 22px;
232	}
233	
234	.section-label {
235	  font-family: var(--font-heading);
236	  font-size: 0.85rem;
237	  font-weight: 700;
238	  text-transform: uppercase;
239	  letter-spacing: 0.06em;
240	  color: var(--text-muted);
241	  display: flex;
242	  align-items: center;
243	  justify-content: space-between;
244	  margin-bottom: 8px;
245	}
246	
247	.section-label span {
248	  display: flex;
249	  align-items: center;
250	  gap: 8px;
251	}
252	
253	/* Preset Chips */
254	.presets-grid {
255	  display: grid;
256	  grid-template-columns: repeat(2, 1fr);
257	  gap: 10px;
258	}
259	
260	.preset-card {
261	  min-height: 54px;
262	  padding: 10px 14px;
263	  background: var(--bg-card);
264	  border: 1px solid var(--border-subtle);
265	  border-radius: var(--radius-md);
266	  cursor: pointer;
267	  display: flex;
268	  flex-direction: column;
269	  justify-content: center;
270	  text-align: left;
271	  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
272	  position: relative;
273	  overflow: hidden;
274	}
275	
276	.preset-card::before {
277	  content: '';
278	  position: absolute;
279	  left: 0;
280	  top: 0;
281	  bottom: 0;
282	  width: 3px;
283	  background: var(--accent-cyan);
284	  opacity: 0;
285	  transition: opacity 0.2s ease;
286	}
287	
288	.preset-card:hover {
289	  background: rgba(255, 255, 255, 0.05);
290	  border-color: rgba(0, 240, 255, 0.4);
291	  transform: translateY(-2px);
292	}
293	
294	.preset-card.active {
295	  background: var(--bg-active);
296	  border-color: var(--accent-cyan);
297	  box-shadow: 0 0 16px rgba(0, 240, 255, 0.15);
298	}
299	
300	.preset-card.active::before {
301	  opacity: 1;
302	}
303	
304	.preset-name {
305	  font-size: 0.85rem;
306	  font-weight: 700;
307	  color: #fff;
308	  white-space: nowrap;
309	  overflow: hidden;
310	  text-overflow: ellipsis;
311	}
312	
313	.preset-tagline {
314	  font-size: 0.7rem;
315	  color: var(--text-dim);
316	  white-space: nowrap;
317	  overflow: hidden;
318	  text-overflow: ellipsis;
319	  margin-top: 2px;
320	}
321	
322	/* Textareas & Inputs */
323	.input-wrapper {
324	  display: flex;
325	  flex-direction: column;
326	  gap: 6px;
327	}
328	
329	.monolithic-textarea {
330	  min-height: 140px;
331	  padding: 14px 16px;
332	  background: var(--bg-input);
333	  border: 1px solid var(--border-subtle);
334	  border-radius: var(--radius-lg);
335	  color: var(--text-main);
336	  font-family: var(--font-body);
337	  font-size: 0.9rem;
338	  line-height: 1.55;
339	  resize: vertical;
340	  outline: none;
341	  transition: all 0.2s ease;
342	}
343	
344	.monolithic-textarea:focus {
345	  border-color: var(--border-focus);
346	  box-shadow: 0 0 0 3px rgba(0, 240, 255, 0.15);
347	}
348	
349	.negative-textarea {
350	  min-height: 72px;
351	  padding: 10px 14px;
352	  background: var(--bg-input);
353	  border: 1px solid var(--border-subtle);
354	  border-radius: var(--radius-md);
355	  color: var(--text-muted);
356	  font-family: var(--font-body);
357	  font-size: 0.8rem;
358	  resize: vertical;
359	  outline: none;
360	}
361	
362	.negative-textarea:focus {
363	  border-color: var(--accent-rose);
364	  box-shadow: 0 0 0 3px rgba(255, 42, 133, 0.15);
365	}
366	
367	/* Aspect Ratio Selector */
368	.ratio-selector {
369	  display: grid;
370	  grid-template-columns: repeat(5, 1fr);
371	  gap: 8px;
372	}
373	
374	.ratio-btn {
375	  min-height: 48px;
376	  display: flex;
377	  flex-direction: column;
378	  align-items: center;
379	  justify-content: center;
380	  background: var(--bg-card);
381	  border: 1px solid var(--border-subtle);
382	  border-radius: var(--radius-md);
383	  color: var(--text-muted);
384	  cursor: pointer;
385	  transition: all 0.2s ease;
386	}
387	
388	.ratio-btn:hover {
389	  background: rgba(255, 255, 255, 0.05);
390	  color: #fff;
391	}
392	
393	.ratio-btn.active {
394	  background: var(--bg-active);
395	  border-color: var(--accent-cyan);
396	  color: var(--accent-cyan);
397	  box-shadow: 0 0 12px rgba(0, 240, 255, 0.2);
398	}
399	
400	.ratio-label {
401	  font-family: var(--font-mono);
402	  font-size: 0.8rem;
403	  font-weight: 700;
404	}
405	
406	.ratio-desc {
407	  font-size: 0.65rem;
408	  color: var(--text-dim);
409	}
410	
411	/* Model Selector */
412	.model-dropdown {
413	  min-height: 48px;
414	  width: 100%;
415	  padding: 0 16px;
416	  background: var(--bg-input);
417	  border: 1px solid var(--border-subtle);
418	  border-radius: var(--radius-md);
419	  color: var(--text-main);
420	  font-family: var(--font-body);
421	  font-size: 0.9rem;
422	  font-weight: 600;
423	  outline: none;
424	  cursor: pointer;
425	}
426	
427	.model-dropdown:focus {
428	  border-color: var(--accent-cyan);
429	}
430	
431	/* Command Button (Monolithic Height Law) */
432	.btn-generate {
433	  min-height: 60px;
434	  width: 100%;
435	  border-radius: var(--radius-lg);
436	  background: linear-gradient(135deg, #00f0ff 0%, #0099ff 50%, #7928ca 100%);
437	  border: none;
438	  color: #07090e;
439	  font-family: var(--font-heading);
440	  font-size: 1.05rem;
441	  font-weight: 800;
442	  letter-spacing: 0.02em;
443	  display: flex;
444	  align-items: center;
445	  justify-content: center;
446	  gap: 12px;
447	  cursor: pointer;
448	  box-shadow: 0 12px 30px rgba(0, 240, 255, 0.35);
449	  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
450	  margin-top: 8px;
451	}
452	
453	.btn-generate:hover:not(:disabled) {
454	  transform: translateY(-2px) scale(1.01);
455	  box-shadow: 0 16px 36px rgba(0, 240, 255, 0.5);
456	}
457	
458	.btn-generate:active:not(:disabled) {
