460	}
461	
462	.btn-generate:disabled {
463	  opacity: 0.6;
464	  cursor: not-allowed;
465	  filter: grayscale(0.5);
466	}
467	
468	/* Right Panel - Canvas Showcase */
469	.canvas-showcase {
470	  padding: 24px;
471	  display: flex;
472	  flex-direction: column;
473	  gap: 20px;
474	  position: relative;
475	}
476	
477	.canvas-viewport {
478	  flex: 1;
479	  min-height: 520px;
480	  background: #090b10;
481	  border: 1px solid var(--border-subtle);
482	  border-radius: var(--radius-xl);
483	  display: flex;
484	  align-items: center;
485	  justify-content: center;
486	  position: relative;
487	  overflow: hidden;
488	}
489	
490	.artwork-render {
491	  max-width: 100%;
492	  max-height: 640px;
493	  object-fit: contain;
494	  border-radius: var(--radius-lg);
495	  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8);
496	  animation: fadeIn 0.4s ease;
497	}
498	
499	@keyframes fadeIn {
500	  from { opacity: 0; transform: scale(0.98); }
501	  to { opacity: 1; transform: scale(1); }
502	}
503	
504	/* Progress State Overlay */
505	.progress-overlay {
506	  position: absolute;
507	  inset: 0;
508	  background: rgba(7, 9, 14, 0.88);
509	  backdrop-filter: blur(12px);
510	  display: flex;
511	  flex-direction: column;
512	  align-items: center;
513	  justify-content: center;
514	  gap: 20px;
515	  z-index: 20;
516	}
517	
518	.progress-spinner {
519	  width: 56px;
520	  height: 56px;
521	  border-radius: 50%;
522	  border: 3px solid rgba(0, 240, 255, 0.15);
523	  border-top-color: var(--accent-cyan);
524	  animation: spin 0.8s linear infinite;
525	}
