import React, { useState } from 'react';
import { BookOpen, Users, Compass, Cpu, Shield, Sparkles } from 'lucide-react';
import type { CodexCategory, CodexEntity } from '../types';

interface CodexViewProps {
  entities: CodexEntity[];
  onForgeEntity: (presetId: string) => void;
}

export const CodexView: React.FC<CodexViewProps> = ({ entities, onForgeEntity }) => {
  const [selectedCategory, setSelectedCategory] = useState<CodexCategory | 'all'>('all');
  const [selectedEntityId, setSelectedEntityId] = useState<string>(entities[0]?.id || '');

  const filteredEntities = selectedCategory === 'all'
    ? entities
    : entities.filter((e) => e.category === selectedCategory);

  const activeEntity = entities.find((e) => e.id === selectedEntityId) || filteredEntities[0] || entities[0];

  const getCategoryIcon = (cat: CodexCategory) => {
    switch (cat) {
      case 'character': return <Users size={14} color="#00f0ff" />;
      case 'location': return <Compass size={14} color="#10b981" />;
      case 'faction': return <Shield size={14} color="#ff2a85" />;
      case 'technology': return <Cpu size={14} color="#a855f7" />;
    }
  };

  return (
    <div style={{ display: 'grid', gridTemplateColumns: '320px 1fr', gap: '24px', alignItems: 'start' }}>
      {/* Left Column: Entity Directory */}
      <div className="glass-panel" style={{ padding: '20px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', borderBottom: '1px solid var(--border-subtle)', paddingBottom: '12px' }}>
          <BookOpen size={18} color="#00f0ff" />
          <h3 style={{ fontFamily: 'var(--font-heading)', fontSize: '1.1rem', color: '#fff' }}>
            World Codex Wiki
          </h3>
          <span style={{ fontSize: '0.7rem', color: 'var(--text-cyan)', marginLeft: 'auto', fontFamily: 'var(--font-mono)' }}>
            {filteredEntities.length} Entities
          </span>
        </div>

        {/* Category Filters */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '6px' }}>
          {(['all', 'character', 'location', 'faction'] as const).map((cat) => (
            <button
              key={cat}
              type="button"
              className={`btn-ghost ${selectedCategory === cat ? 'active' : ''}`}
              style={{
                minHeight: '44px',
                fontSize: '0.75rem',
                justifyContent: 'center',
                textTransform: 'capitalize',
                background: selectedCategory === cat ? 'var(--bg-active)' : 'var(--bg-input)',
                borderColor: selectedCategory === cat ? 'var(--accent-cyan)' : 'var(--border-subtle)',
                color: selectedCategory === cat ? 'var(--accent-cyan)' : 'var(--text-muted)'
              }}
              onClick={() => setSelectedCategory(cat)}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Directory List */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', maxHeight: '560px', overflowY: 'auto' }}>
          {filteredEntities.map((entity) => (
            <div
              key={entity.id}
              onClick={() => setSelectedEntityId(entity.id)}
              style={{
                minHeight: '52px',
                padding: '10px 14px',
                borderRadius: 'var(--radius-md)',
                background: activeEntity?.id === entity.id ? 'var(--bg-active)' : 'rgba(255, 255, 255, 0.02)',
                border: `1px solid ${activeEntity?.id === entity.id ? entity.accent : 'var(--border-subtle)'}`,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                transition: 'var(--transition-fast)'
              }}
            >
              <div style={{
                width: '32px',
                height: '32px',
                borderRadius: '8px',
                background: 'rgba(255, 255, 255, 0.05)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}>
                {getCategoryIcon(entity.category)}
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', minWidth: 0, flex: 1 }}>
                <div style={{ fontSize: '0.88rem', fontWeight: 700, color: '#fff', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {entity.name}
                </div>
                <div style={{ fontSize: '0.72rem', color: 'var(--text-dim)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {entity.role}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Right Column: Detailed Dossier Sheet */}
      {activeEntity && (
        <div className="glass-panel" style={{ padding: '28px', display: 'flex', flexDirection: 'column', gap: '24px' }}>
          {/* Header Row */}
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', borderBottom: '1px solid var(--border-subtle)', paddingBottom: '20px' }}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <span style={{
                  padding: '2px 8px',
                  borderRadius: '4px',
                  fontSize: '0.7rem',
                  fontWeight: 700,
                  textTransform: 'uppercase',
                  background: `${activeEntity.accent}20`,
                  color: activeEntity.accent,
                  border: `1px solid ${activeEntity.accent}40`,
                  fontFamily: 'var(--font-mono)'
                }}>
                  {activeEntity.category}
                </span>
                <h2 style={{ fontFamily: 'var(--font-heading)', fontSize: '1.75rem', color: '#fff' }}>
                  {activeEntity.name}
                </h2>
              </div>
              <div style={{ fontSize: '0.95rem', color: activeEntity.accent, fontWeight: 600 }}>
                {activeEntity.role}
              </div>
              <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', maxWidth: '640px', lineHeight: '1.5' }}>
                {activeEntity.tagline}
              </p>
            </div>

            {/* Forge Button */}
            {activeEntity.promptPresetId && (
              <button
                type="button"
                className="btn-generate"
                style={{
                  minHeight: '48px',
                  width: 'auto',
                  padding: '0 20px',
                  background: `linear-gradient(135deg, ${activeEntity.accent} 0%, #1a1a2e 100%)`,
                  borderColor: activeEntity.accent
                }}
                onClick={() => onForgeEntity(activeEntity.promptPresetId!)}
              >
                <Sparkles size={16} />
                <span>Forge Visual in Studio</span>
              </button>
            )}
          </div>

          {/* Quick Stats Grid */}
          {(activeEntity.age || activeEntity.height) && (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '12px' }}>
              {activeEntity.age && (
                <div style={{ background: 'var(--bg-input)', padding: '12px 16px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-subtle)' }}>
                  <div style={{ fontSize: '0.7rem', color: 'var(--text-dim)', textTransform: 'uppercase', fontWeight: 700 }}>Age</div>
                  <div style={{ fontSize: '1rem', color: '#fff', fontWeight: 600 }}>{activeEntity.age}</div>
                </div>
              )}
              {activeEntity.height && (
                <div style={{ background: 'var(--bg-input)', padding: '12px 16px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-subtle)' }}>
                  <div style={{ fontSize: '0.7rem', color: 'var(--text-dim)', textTransform: 'uppercase', fontWeight: 700 }}>Height</div>
                  <div style={{ fontSize: '1rem', color: '#fff', fontWeight: 600 }}>{activeEntity.height}</div>
                </div>
              )}
            </div>
          )}

          {/* Visual Archetype & Tags */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div className="section-label">
              <span>Visual Signature & Style Tags</span>
            </div>
            <div style={{
              background: 'var(--bg-input)',
              padding: '14px 18px',
              borderRadius: 'var(--radius-md)',
              border: '1px solid var(--border-subtle)',
              fontFamily: 'var(--font-mono)',
              fontSize: '0.82rem',
              color: 'var(--text-cyan)',
              lineHeight: '1.6'
            }}>
              {activeEntity.visualTags}
            </div>
          </div>

          {/* Psychology & Dynamic */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div className="section-label">
              <span>Psychological Architecture & Behavioral Matrix</span>
            </div>
            <p style={{
              fontSize: '0.88rem',
              color: 'var(--text-muted)',
              lineHeight: '1.6',
              background: 'rgba(255, 255, 255, 0.01)',
              padding: '16px',
              borderRadius: 'var(--radius-md)',
              border: '1px solid var(--border-subtle)'
            }}>
              {activeEntity.psychology}
            </p>
          </div>

          {/* Backstory & Origin */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div className="section-label">
              <span>Historical Origin & Lore Context</span>
            </div>
            <p style={{
              fontSize: '0.88rem',
              color: 'var(--text-muted)',
              lineHeight: '1.6',
              background: 'rgba(255, 255, 255, 0.01)',
              padding: '16px',
              borderRadius: 'var(--radius-md)',
              border: '1px solid var(--border-subtle)'
            }}>
              {activeEntity.backstory}
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

