export type AspectRatio = '1:1' | '2:3' | '3:4' | '9:16' | '16:9';

export type EngineProvider = 'gemini-imagen' | 'flux-free' | 'pixai';

export interface ModelOption {
  id: string;
  name: string;
  series: string;
  badge: string;
  description: string;
  samplePrompt: string;
  provider: EngineProvider;
}

export type GenerationStatus = 'idle' | 'submitting' | 'queued' | 'denoising' | 'decoding' | 'completed' | 'error';

export interface ArtAsset {
  id: string;
  prompt: string;
  negativePrompt: string;
  modelId: string;
  modelName: string;
  aspectRatio: AspectRatio;
  imageUrl: string;
  createdAt: string;
  seed: number;
  isLiveApi: boolean;
  provider: EngineProvider;
  character?: string;
}

export interface PresetItem {
  id: string;
  title: string;
  character: string;
  tagline: string;
  prompt: string;
  negativePrompt: string;
  ratio: AspectRatio;
  modelId: string;
  accent: string;
  previewUrl: string;
}

